<?php
declare(strict_types=1);

/*
 * PAY-001 Phase 2d — UI visibility correction.
 *
 * Restores product/checkout credit UI while Monobank onboarding is incomplete.
 * The deployed Mono controller still requires point_id at the final server-side
 * confirm boundary, so this patch cannot send an incomplete bank application.
 *
 * No DB/settings changes. Rollback: restore the two files from the printed backup.
 */

$patch_id = pathinfo(__FILE__, PATHINFO_FILENAME);
$root = getcwd();
$manifest = json_decode(base64_decode('', true), true, 512, JSON_THROW_ON_ERROR);

function pay001ui_fail(string $message, int $code = 1): never {
    fwrite(STDERR, 'error=' . $message . PHP_EOL);
    exit($code);
}

function pay001ui_lint(string $file): void {
    $command = escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg($file) . ' 2>&1';
    $output = [];
    $status = 0;
    exec($command, $output, $status);

    if ($status !== 0) {
        throw new RuntimeException('php_l_failed file=' . $file . ' output=' . implode(' | ', $output));
    }
}

function pay001ui_restore(string $root, string $backup, array $manifest): void {
    foreach (array_keys($manifest) as $relative) {
        $saved = $backup . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);

        if (is_file($saved)) {
            @copy($saved, $target);
        }
    }
}

try {
    pay001ui_lint(__FILE__);
} catch (Throwable $error) {
    pay001ui_fail($error->getMessage());
}

if (!is_file($root . DIRECTORY_SEPARATOR . 'config.php')) {
    pay001ui_fail('run_from_opencart_root_config_missing');
}

$old_count = 0;
$new_count = 0;

foreach ($manifest as $relative => $spec) {
    $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);

    if (!is_file($target)) {
        pay001ui_fail('target_missing file=' . $relative);
    }

    $hash = hash_file('sha256', $target);

    if (hash_equals($spec['new_sha256'], $hash)) {
        $new_count++;
        continue;
    }

    if (!hash_equals($spec['old_sha256'], $hash)) {
        pay001ui_fail('source_sha256_mismatch file=' . $relative . ' expected=' . $spec['old_sha256'] . ' actual=' . $hash);
    }

    $source = file_get_contents($target);

    if (!is_string($source)) {
        pay001ui_fail('read_failed file=' . $relative);
    }

    $anchor_count = substr_count($source, (string)$spec['anchor']);

    if ($anchor_count !== (int)$spec['anchor_count']) {
        pay001ui_fail('anchor_count file=' . $relative . ' expected=' . $spec['anchor_count'] . ' actual=' . $anchor_count);
    }

    $old_count++;
}

if ($new_count === count($manifest)) {
    echo 'already_applied=yes' . PHP_EOL;
    @unlink(__FILE__);
    exit(0);
}

if ($new_count > 0 || $old_count !== count($manifest)) {
    pay001ui_fail('mixed_source_state old=' . $old_count . ' new=' . $new_count);
}

$timestamp = date('Ymd-His');
$backup = $root . DIRECTORY_SEPARATOR . '_patch_backups' . DIRECTORY_SEPARATOR . $patch_id . '-' . $timestamp;

foreach (array_keys($manifest) as $relative) {
    $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
    $saved = $backup . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
    $saved_dir = dirname($saved);

    if (!is_dir($saved_dir) && !mkdir($saved_dir, 0775, true) && !is_dir($saved_dir)) {
        pay001ui_fail('backup_dir_failed path=' . $saved_dir);
    }

    if (!copy($target, $saved)) {
        pay001ui_fail('backup_failed file=' . $relative);
    }
}

echo 'cwd=' . $root . PHP_EOL;
echo 'time=' . date(DATE_ATOM) . PHP_EOL;
echo 'backup=' . $backup . PHP_EOL;

try {
    foreach ($manifest as $relative => $spec) {
        $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        $content = base64_decode((string)$spec['content_base64'], true);

        if (!is_string($content)) {
            throw new RuntimeException('decode_failed file=' . $relative);
        }

        if (file_put_contents($target, $content, LOCK_EX) !== strlen($content)) {
            throw new RuntimeException('write_failed file=' . $relative);
        }

        if (!hash_equals($spec['new_sha256'], hash_file('sha256', $target))) {
            throw new RuntimeException('post_write_sha256_mismatch file=' . $relative);
        }

        echo 'changed_file=' . $relative . PHP_EOL;
    }

    foreach (array_keys($manifest) as $relative) {
        pay001ui_lint($root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative));
    }
} catch (Throwable $error) {
    pay001ui_restore($root, $backup, $manifest);
    pay001ui_fail($error->getMessage() . ' restored=yes');
}

echo 'php_l=ok' . PHP_EOL;
echo 'done=ok' . PHP_EOL;
@unlink(__FILE__);